// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(c), amount);
        uint256 preBalance = address(c).balance;
        vm.prank(address(this));
        c.withdrawAll(address(0x1234));
        uint256 postBalance = address(c).balance;
        assertTrue(postBalance < preBalance, "Balance should decrease when contract has ether");
    }
}

